    44	/// One read `set_graphic` patch: each field `None` when its key was absent.
    45	struct GraphicPatch {
    46	    name: Option<String>,
    47	    width: Option<u32>,
    48	    height: Option<u32>,
    49	    /// The outer `Option` is "was the key given"; the inner is what to
    50	    /// store, `None` for a `null`, which gives the length back to the
    51	    /// clip's duration.
    52	    length: Option<Option<Ticks>>,
    53	    /// Checked and normalised, `null`s kept as removals.
    54	    props: Option<Map<String, Value>>,
    55	}
    56	
    57	impl Project {
    58	    /// A graphic clip at `at` on `track`, drawn by `graphics/<name>.js` at
    59	    /// `width` × `height` (the canvas's when absent), five seconds long
    60	    /// unless `duration` says otherwise, with `props` checked against
    61	    /// `schema` when one is given (G-4). Fit scale, as a shape's box is.
    62	    ///
    63	    /// Refuses on an overlap-rule violation, in the rule's own sentence;
    64	    /// `Err` for a bad name, a side outside 1–8192 (or a canvas side over
    65	    /// it with no size given), a malformed schema, a bad prop, more than
    66	    /// 64 props, an unknown track or a duration under a frame.
    67	    #[allow(clippy::too_many_arguments)]
    68	    pub fn add_graphic_clip(
    69	        &self,
    70	        track: u32,
    71	        at: Ticks,
    72	        duration: Option<Ticks>,
    73	        name: &str,
    74	        width: Option<u32>,
    75	        height: Option<u32>,
    76	        props: Option<&Value>,
    77	        schema: Option<&Value>,
    78	    ) -> Result<Outcome, String> {
    79	        check_name(name)?;
    80	        let width = self.graphic_side("width", width)?;
    81	        let height = self.graphic_side("height", height)?;
    82	        if let Some(schema) = schema {
    83	            check_schema(schema)?;
    84	        }
    85	        let props = match props {
    86	            None => Map::new(),
    87	            Some(value) => {
    88	                let patch = value.as_object().ok_or_else(|| {
    89	                    format!("props must be a json object, not {}", describe(value))
    90	                })?;
    91	                let mut stored = check_props(patch, schema)?;
    92	                stored.retain(|_, value| !value.is_null());
    93	                check_count(&stored)?;
    94	                stored
    95	            }
    96	        };
    97	        // A graphic's size IS its source size, so an oversized one fits
    98	        // like oversized footage does — the shape's rule.
    99	        let scale = self.fit_scale(f64::from(width), f64::from(height));
   100	        self.add_described_clip(
   101	            track,
   102	            at,
   103	            duration,
   104	            Described {
   105	                source: Source::Graphic,
   106	                scale,
   107	                text: None,
   108	                shape: None,
   109	                graphic: Some(GraphicProps {
   110	                    name: name.to_string(),
   111	                    width,
   112	                    height,
   113	                    r#in: 0,
   114	                    length: None,
   115	                    props,
   116	                }),
   117	            },
   118	        )
   119	    }
   120	
   121	    /// Patches each named graphic clip's `name`, `width`, `height`,
   122	    /// `length` and `props` (road map 10 §5h). `props` merges key by key and
   123	    /// a `null` removes its key — except, with a `schema`, a prop an action
   124	    /// on the clip names, which takes the schema's default (G-34 (d)); `in`
   125	    /// is not patchable, because the trims and `split` own it (G-9).
   126	    ///
   127	    /// `Err` for a malformed schema, a patch that is not an object, an
   128	    /// unknown clip, a clip that is not a graphic, an unknown key and any
   129	    /// value its check refuses; an identity when nothing changes — a colour
   130	    /// re-sent in another spelling included. No rule refuses a patch, as
   131	    /// none refuses `set_shape`'s.
   132	    pub fn set_graphic(
   133	        &self,
   134	        clips: &[u32],
   135	        patch: &Value,
   136	        schema: Option<&Value>,
   137	    ) -> Result<Outcome, String> {
   138	        if let Some(schema) = schema {
   139	            check_schema(schema)?;
   140	        }
   141	        let Some(fields) = patch.as_object() else {
   142	            return Err(format!(
   143	                "graphic patch must be a json object, not {}",
   144	                describe(patch)
   145	            ));
   146	        };
   147	        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();
   148	        if ids.is_empty() {
   149	            return Ok(Outcome::Identity);
   150	        }
   151	        for id in &ids {
   152	            let clip = self.require_clip(*id)?;
   153	            if !(matches!(clip.source, Source::Graphic) && clip.graphic.is_some()) {
   154	                return Err(format!("clip {id} is not a graphic clip"));
   155	            }
   156	        }
   157	        let read = self.read_graphic_patch(fields, schema)?;
   158	
   159	        let mut next = self.clone();
   160	        for id in ids {
   161	            let Some(original) = self.clip(id) else {
   162	                continue;
   163	            };
   164	            let Some(graphic) = next.clip_mut(id).and_then(|clip| clip.graphic.as_mut()) else {
   165	                continue;
   166	            };
   167	            if let Some(name) = &read.name {
   168	                graphic.name = name.clone();
   169	            }
   170	            if let Some(width) = read.width {
   171	                graphic.width = width;
   172	            }
   173	            if let Some(height) = read.height {
   174	                graphic.height = height;
   175	            }
   176	            if let Some(length) = read.length {
   177	                graphic.length = length;
   178	            }
   179	            if let Some(props) = &read.props {
   180	                for (key, value) in props {
   181	                    let kept = schema
   182	                        .and_then(|schema| schema_default(schema, key))
   183	                        .filter(|_| value.is_null() && names_prop(original, key));
   184	                    if let Some(default) = kept {
   185	                        graphic.props.insert(key.clone(), default);
   186	                    } else if value.is_null() {
   187	                        graphic.props.shift_remove(key);
   188	                    } else {
   189	                        graphic.props.insert(key.clone(), value.clone());
   190	                    }
   191	                }
   192	                check_count(&graphic.props)?;
   193	            }
   194	        }
   195	        self.finish(next)
   196	    }
   197	
   198	    /// A side the caller gave, checked; or the canvas's same side, which a
   199	    /// graphic cannot draw at when it is over the bound. Only the defaulted
   200	    /// side is tested, so a caller who gave the other one is not refused
   201	    /// for it.
   202	    fn graphic_side(&self, key: &str, given: Option<u32>) -> Result<u32, String> {
   203	        match given {
   204	            Some(side) => {
   205	                check_side(key, u64::from(side))?;
   206	                Ok(side)
   207	            }
   208	            None => {
   209	                let (width, height) = (self.canvas.width, self.canvas.height);
   210	                let side = if key == "width" { width } else { height };
   211	                if side > GRAPHIC_MAX_SIDE {
   212	                    return Err(format!(
   213	                        "the canvas is {width}×{height} and a graphic's side is at most \
   214	                         {GRAPHIC_MAX_SIDE}; pass width and height"
   215	                    ));
   216	                }
   217	                Ok(side)
   218	            }
   219	        }
   220	    }
   221	
   222	    /// Reads a `set_graphic` patch key by key, every value checked before
   223	    /// any is applied, ticks snapped after their check.
   224	    fn read_graphic_patch(
   225	        &self,
   226	        fields: &Map<String, Value>,
   227	        schema: Option<&Value>,
   228	    ) -> Result<GraphicPatch, String> {
   229	        let mut read = GraphicPatch {
   230	            name: None,
   231	            width: None,
   232	            height: None,
   233	            length: None,
   234	            props: None,
   235	        };
   236	        for (key, value) in fields {
   237	            match key.as_str() {
   238	                "name" => {
   239	                    let name = value
   240	                        .as_str()
   241	                        .ok_or_else(|| format!("name must be a string, not {}", describe(value)))?;
   242	                    check_name(name)?;
   243	                    read.name = Some(name.to_string());
   244	                }
   245	                "width" | "height" => {
   246	                    let side = value.as_u64().ok_or_else(|| {
   247	                        format!("{key} must be a whole number, not {}", describe(value))
   248	                    })?;
   249	                    check_side(key, side)?;
   250	                    // Inside 1–8192, so the narrowing cannot fail.
   251	                    let side = u32::try_from(side).unwrap_or(GRAPHIC_MAX_SIDE);
   252	                    if key == "width" {
   253	                        read.width = Some(side);
   254	                    } else {
   255	                        read.height = Some(side);
   256	                    }
   257	                }
   258	                "length" => read.length = Some(self.graphic_length(value)?),
   259	                "props" => {
   260	                    let patch = value.as_object().ok_or_else(|| {
   261	                        format!("props must be a json object, not {}", describe(value))
   262	                    })?;
   263	                    read.props = Some(check_props(patch, schema)?);
   264	                }
   265	                "in" => {
   266	                    return Err(
   267	                        "\"in\" cannot be patched: trim_start and split own a graphic's in point"
   268	                            .to_string(),
   269	                    )
   270	                }
   271	                other => return Err(unknown_key(other, "a graphic patch")),
   272	            }
   273	        }
   274	        Ok(read)
   275	    }
   276	
   277	    /// `null` gives the length back to the clip's duration; a number is
   278	    /// snapped to the nearest frame, and under one frame is an `Err` naming
   279	    /// what was sent.
   280	    fn graphic_length(&self, value: &Value) -> Result<Option<Ticks>, String> {
   281	        if value.is_null() {
   282	            return Ok(None);
   283	        }
   284	        let given = value.as_i64().ok_or_else(|| {
   285	            format!(
   286	                "length must be a whole number of ticks or null, not {}",
   287	                describe(value)
   288	            )
   289	        })?;
   290	        let snapped = self.snapped(given);
   291	        if snapped < self.frame() {
   292	            return Err(format!(
   293	                "length must be at least one frame ({} ticks), not {given}",
   294	                self.frame()
   295	            ));
   296	        }
   297	        Ok(Some(snapped))
   298	    }
   299	}
    func addGeneratedClip(
        named name: String, grouped: Bool = false, _ make: (UInt32, Ticks) -> ReelOp
    ) {
        guard let document = document else { return }
        // The EDITED project throughout, here and in every other command in
        // this file that places a clip: with a nest open the front track is
        // the NEST's front track, the overlap probe has to be run against the
        // nest, and the id set the selection is read back out of is the
        // nest's (road map 2's phase 9). `add_media` is the one exception and
        // is called out where it happens.
        let before = document.editedProject.snapshot
        let ops = Self.generatedClipOps(in: document, make)
        if grouped {
            document.performGroupedEdit(name, ops)
        } else {
            document.applyEdit(name, ops)
        }
        selectClips(addedSince: before, in: document)
    }

    /// The track choice alone, no edit: `make` at the playhead on the
    /// edited project's front track when it fits there, else a new track
    /// above everything and `make` on it. `insert_graphic` places its clip
    /// by it too (spec §11 G-16 (a), G-45 (f)).
    static func generatedClipOps(
        in document: ProjectDocument, _ make: (UInt32, Ticks) -> ReelOp
    ) -> [ReelOp] {
        let before = document.editedProject.snapshot
        let at = document.playhead
        // `.project` on a `try?` collapses three answers into one nil: a
        // throw, an identity and a rule's refusal. Either way the front track
        // will not take this clip, so all of them take the new-track path.
        if let front = before.tracks.last?.id,
            (try? document.editedProject.applying(make(front, at))).project != nil
        {
            return [make(front, at)]
        }
        // The id of a newly added track is `next_id` from BEFORE the op —
        // the documented contract of the one JSON op entry point, since
        // `rc_project_apply` returns a project rather than an id.
        // Index 0 is the BACK of the stack (§6), so the count is the front.
        return [.addTrack(index: before.tracks.count), make(before.nextId, at)]
    }

    /// Select whatever appeared, so the inspector opens on the new clip's own
    /// sections and the canvas draws its handles. Comparing id sets rather
    /// than trusting an id we predicted keeps this correct even if the core
    /// ever allocates differently — and it is why every command in this file
    /// reads the snapshot BEFORE it edits.
    ///
    /// Nothing added means the core refused or answered an identity —
    /// `applyEdit` has already beeped — so the selection stays as
    /// `ProjectDocument.clampViewState` left it.
    func selectClips(addedSince before: ProjectSnapshot, in document: ProjectDocument) {
        let existing = Set(before.clips.map { $0.id })
        let added = document.editedProject.snapshot.clips.map { $0.id }
            .filter { !existing.contains($0) }
        guard !added.isEmpty else { return }
        document.selection = Set(added)
        viewStateDidChange()
    }

