131	   131	fn check_entry(key: &str, entry: &Value) -> Result<(), String> {
132	   132	    if !is_name(key) {
133	   133	        return Err(format!(
134	   134	            "schema key \"{key}\" is not a name (letters, digits and _, starting with a letter or _, at most 32 characters)"
135	   135	        ));
136	   136	    }
137	   137	    let Some(kind) = entry.get("type").and_then(Value::as_str) else {
138	   138	        return Err(format!("schema.{key} must be an object with a type"));
139	   139	    };
140	   140	    if !GRAPHIC_TYPES.contains(&kind) {
141	   141	        return Err(format!(
142	   142	            "schema.{key}.type \"{kind}\" is not one of string, number, boolean, color, enum, asset"
143	   143	        ));
144	   144	    }
145	   145	    if kind == "enum" {
146	   146	        let good = entry
147	   147	            .get("options")
148	   148	            .and_then(Value::as_array)
149	   149	            .is_some_and(|o| {
150	   150	                (1..=GRAPHIC_MAX_OPTIONS).contains(&o.len()) && o.iter().all(Value::is_string)
151	   151	            });
152	   152	        if !good {
153	   153	            return Err(format!("schema.{key}.options must be 1–32 strings"));
154	   154	        }
155	   155	    }
