157	   157	        return Err(format!("schema.{key} has no default"));
158	   158	    };
159	   159	    let fits = match kind {
160	   160	        "string" => default
161	   161	            .as_str()
162	   162	            .is_some_and(|s| s.chars().count() <= GRAPHIC_MAX_STRING),
163	   163	        "color" => default.as_str().and_then(normalise_color).is_some(),
164	   164	        "number" => default.as_f64().is_some_and(f64::is_finite),
165	   165	        "boolean" => default.is_boolean(),
166	   166	        "enum" => options(entry).contains(default),
167	   167	        "asset" => default.is_string() || default.is_null(),
