196	   196	/// A `props` patch checked key by key, answered as the copy to merge: each
197	   197	/// `color` normalised, every `null` KEPT as a removal for the caller. With
198	   198	/// a schema, each non-null key must be an entry and each value its type,
199	   199	/// range and membership — a `null` is exempt, so a key stored before the
200	   200	/// module dropped it can still be removed; without one only the shape is
201	   201	/// checked. The key COUNT is
202	   202	/// [`check_count`]'s, on the object about to be stored.
203	   203	pub(crate) fn check_props(
204	   204	    patch: &Map<String, Value>,
205	   205	    schema: Option<&Value>,
206	   206	) -> Result<Map<String, Value>, String> {
207	   207	    let mut checked = Map::new();
208	   208	    for (key, value) in patch {
209	   209	        let value = match schema {
210	   210	            // A removal is never checked, so a stale key can be cleared.
211	   211	            Some(_) if value.is_null() => Value::Null,
212	   212	            Some(schema) => {
213	   213	                let Some(entry) = schema.get(key) else {
214	   214	                    return Err(crate::patch::unknown_key(
215	   215	                        &format!("props.{key}"),
216	   216	                        "a graphic patch",
217	   217	                    ));
218	   218	                };
219	   219	                check_typed(key, entry, value)?
220	   220	            }
221	   221	            None => {
222	   222	                check_shape_only(key, value)?;
223	   223	                value.clone()
224	   224	            }
225	   225	        };
226	   226	        checked.insert(key.clone(), value);
227	   227	    }
228	   228	    Ok(checked)
229	   229	}
