231	   231	/// One value against its schema entry, answered normalised.
232	   232	pub(crate) fn check_typed(key: &str, entry: &Value, value: &Value) -> Result<Value, String> {
233	   233	    let kind = entry.get("type").and_then(Value::as_str).unwrap_or("");
234	   234	    let wrong = |what: &str| format!("props.{key} must be {what}, not {}", describe(value));
235	   235	    match kind {
236	   236	        "string" => {
237	   237	            let text = value.as_str().ok_or_else(|| wrong("a string"))?;
238	   238	            check_length(key, text)?;
239	   239	        }
240	   240	        "number" => {
241	   241	            let number = value
242	   242	                .as_f64()
243	   243	                .filter(|n| n.is_finite())
244	   244	                .ok_or_else(|| wrong("a number"))?;
245	   245	            check_range(key, entry, number, value)?;
246	   246	        }
247	   247	        "boolean" => {
248	   248	            value.as_bool().ok_or_else(|| wrong("a boolean"))?;
249	   249	        }
250	   250	        "color" => {
251	   251	            let colour = value.as_str().and_then(normalise_color).ok_or_else(|| {
252	   252	                wrong("a CSS colour (#rgb, #rgba, #rrggbb, #rrggbbaa, rgb(), rgba(), hsl(), hsla() or a colour name)")
253	   253	            })?;
254	   254	            return Ok(Value::String(colour));
255	   255	        }
256	   256	        "enum" => {
257	   257	            let listed = options(entry);
258	   258	            if !listed.contains(value) {
259	   259	                let names: Vec<&str> = listed.iter().filter_map(Value::as_str).collect();
260	   260	                return Err(wrong(&format!("one of {}", names.join(", "))));
261	   261	            }
262	   262	        }
263	   263	        "asset" => {
264	   264	            value
265	   265	                .as_str()
266	   266	                .ok_or_else(|| wrong("an asset's file name or null"))?;
267	   267	        }
268	   268	        // `check_schema` refuses any other type, and a schema reaches here
269	   269	        // only through it.
270	   270	        _ => return Err(wrong(&format!("a {kind}"))),
271	   271	    }
272	   272	    Ok(value.clone())
273	   273	}
