275	   275	/// A number inside its entry's `min` and `max`, either of which may be
276	   276	/// absent. `step` is a hint to the inspector's slider, not a rule.
277	   277	fn check_range(key: &str, entry: &Value, number: f64, value: &Value) -> Result<(), String> {
278	   278	    let min = entry.get("min").filter(|m| m.is_number());
279	   279	    let max = entry.get("max").filter(|m| m.is_number());
280	   280	    let below = min.and_then(Value::as_f64).is_some_and(|m| number < m);
281	   281	    let above = max.and_then(Value::as_f64).is_some_and(|m| number > m);
282	   282	    if !(below || above) {
283	   283	        return Ok(());
284	   284	    }
285	   285	    let bounds = match (min, max) {
286	   286	        (Some(min), Some(max)) => format!("between {min} and {max}"),
287	   287	        (Some(min), None) => format!("at least {min}"),
288	   288	        (None, Some(max)) => format!("at most {max}"),
289	   289	        // Outside no bound is inside every bound.
290	   290	        (None, None) => return Ok(()),
291	   291	    };
292	   292	    Err(format!("props.{key} must be {bounds}, not {value}"))
293	   293	}
