55	    55	    /// The props of each variant G-46 (b) draws: one per `enum` option other than its
56	    56	    /// default and one per boolean's opposite, in schema order, at most `maxVariants`.
57	    57	    static func variants(_ schema: GraphicSchema) -> [[String: Any]] {
58	    58	        var out: [[String: Any]] = []
59	    59	        for entry in schema.entries {
60	    60	            switch (entry.type, entry.default) {
61	    61	            case ("enum", let value):
62	    62	                let current: String? = { if case .string(let s) = value { return s }; return nil }()
63	    63	                for option in entry.options where option != current {
64	    64	                    out.append([entry.key: option])
65	    65	                }
66	    66	            case ("boolean", .bool(let flag)):
67	    67	                out.append([entry.key: !flag])
68	    68	            default:
69	    69	                continue
70	    70	            }
71	    71	        }
72	    72	        return Array(out.prefix(maxVariants))
