180	   180	    /// Compiles, draws by G-46 (b)'s rule, and writes the package at `url`, replacing a file
181	   181	    /// there. Never on main and never on GCD: the sheet's 8 MiB `Thread` or the agent's server
182	   182	    /// thread. Throws a sentence, writing nothing, for a module that does not compile.
183	   183	    func write(to url: URL) throws -> GraphicPackageResult {
184	   184	        let module: GraphicModule
185	   185	        do {
186	   186	            module = try GraphicModule.compile(
187	   187	                library: library, name: name, source: String(decoding: source, as: UTF8.self),
188	   188	                budgetMs: GraphicRegistry.offlineBudgetMs)
189	   189	        } catch {
190	   190	            let first = GraphicDiagnostic.of(error).first
191	   191	            let line = first?.line.map { " (line \($0))" } ?? ""
192	   192	            throw ReelCoreError(
193	   193	                message: "\(label) does not compile: " + (first?.message ?? "no diagnostic")
194	   194	                    + line)
195	   195	        }
196	   196	        let describe = module.describeJSON()
197	   197	        let described = (try? JSONSerialization.jsonObject(with: Data(describe.utf8)))
198	   198	            as? [String: Any]
199	   199	        let schema = GraphicSchema(
200	   200	            describeJSON: describe, schema: described?["schema"] as? [String: Any] ?? [:])
201	   201	        var frames = 0, failed = 0
202	   202	        let sample = { (frame: Int, props: [String: Any]) in
203	   203	            frames += 1
204	   204	            if !self.draw(module, frame: frame, props: props) { failed += 1 }
205	   205	        }
206	   206	        for frame in GraphicPackage.sampledFrames(length: length, cap: GraphicPackage.maxFrames) {
207	   207	            sample(frame, [:])
208	   208	        }
209	   209	        let variantFrames = GraphicPackage.sampledFrames(
210	   210	            length: length, cap: GraphicPackage.variantFrames)
211	   211	        for props in GraphicPackage.variants(schema) {
212	   212	            for frame in variantFrames { sample(frame, props) }
213	   213	        }
214	   214	
215	   215	        let usage = library.usage()
216	   216	        let usedFonts = usage.fonts.compactMap { fonts.indices.contains($0) ? fonts[$0] : nil }
217	   217	        let usedAssets = usage.assets.compactMap { used in assets.first { $0.name == used } }
218	   218	        var listed: [[String: Any]] = [["path": "\(name).js", "size": source.count]]
219	   219	        var data = source
220	   220	        for (folder, files) in [
221	   221	            (GraphicStore.fontsFolderName, usedFonts), (GraphicStore.assetsFolderName, usedAssets),
222	   222	        ] {
223	   223	            for file in files {
224	   224	                listed.append(["path": "\(folder)/\(file.name)", "size": file.bytes.count])
225	   225	                data.append(file.bytes)
226	   226	            }
227	   227	        }
228	   228	        let spec: [String: Any] = [
229	   229	            "module": name, "title": title, "category": category,
230	   230	            "description": description ?? NSNull(), "app_version": appVersion, "files": listed,
231	   231	        ]
