233	   233	            decoding: try JSONSerialization.data(withJSONObject: spec), as: UTF8.self)
234	   234	
235	   235	        let partial = url.deletingLastPathComponent()
236	   236	            .appendingPathComponent(".\(url.lastPathComponent).partial")
