238	   238	        do {
239	   239	            manifest = try ReelGraphicPackage.write(
240	   240	                path: partial.path, packageJSON: specJSON, data: data)
241	   241	            guard rename(partial.path, url.path) == 0 else {
242	   242	                let why = String(cString: strerror(errno))
