244	   244	            }
245	   245	        } catch {
246	   246	            try? FileManager.default.removeItem(at: partial)
247	   247	            throw error
248	   248	        }
249	   249	        let parsed = (try? JSONSerialization.jsonObject(with: Data(manifest.utf8)))
250	   250	            as? [String: Any]
251	   251	        let paths = (parsed?["files"] as? [[String: Any]] ?? [])
252	   252	            .compactMap { $0["path"] as? String }
253	   253	        return GraphicPackageResult(url: url, files: paths, frames: frames, failedFrames: failed)
254	   254	    }
