319	    45	    /// Reads the file at `url` and checks it, the core's checks then the app's.
320	    46	    static func read(at url: URL) throws -> GraphicPackageContents {
321	    47	        let refuse = { (sentence: String) in
322	    48	            ReelCoreError(message: "\(url.lastPathComponent) cannot be imported: \(sentence)")
323	    49	        }
324	    50	        let values = try? url.resourceValues(forKeys: [.isRegularFileKey, .fileSizeKey])
325	    51	        guard values?.isRegularFile == true else { throw refuse("it is not a file") }
326	    52	        let size = values?.fileSize ?? 0
327	    53	        guard size > 0 else { throw refuse("it is empty (0 bytes)") }
328	    54	        guard UInt64(size) <= UInt64(UInt32.max) else {
329	    55	            throw refuse("it is \(size) bytes, more than a .fjgraphic holds (\(UInt32.max))")
330	    56	        }
331	    57	        let data: Data
332	    58	        do {
333	    59	            data = try Data(contentsOf: url)
334	    60	        } catch {
335	    61	            throw refuse("it could not be read: \(error.localizedDescription)")
336	    62	        }
337	    63	        let answer: String
338	    64	        do {
339	    65	            answer = try ReelGraphicPackage.read(data)
340	    66	        } catch let error as ReelCoreError {
341	    67	            throw refuse(error.message)
342	    68	        }
343	    69	        guard let manifest = (try? JSONSerialization.jsonObject(with: Data(answer.utf8)))
344	    70	            as? [String: Any], let files = manifest["files"] as? [[String: Any]],
345	    71	            let first = files.first
346	    72	        else { throw refuse("the core's answer could not be read") }
347	    73	        func bytes(_ file: [String: Any]) -> Data {
348	    74	            let offset = file["offset"] as? Int ?? 0, length = file["size"] as? Int ?? 0
349	    75	            return data.subdata(in: offset..<(offset + length))
350	    76	        }
351	    77	        var fonts: [GraphicPackageFile] = [], assets: [GraphicPackageFile] = []
352	    78	        for file in files.dropFirst() {
353	    79	            let entry = GraphicPackageFile(name: file["name"] as? String ?? "", bytes: bytes(file))
354	    80	            let path = file["path"] as? String ?? ""
355	    81	            if path.hasPrefix(GraphicStore.fontsFolderName + "/") {
356	    82	                fonts.append(entry)
357	    83	            } else {
358	    84	                assets.append(entry)
359	    85	            }
360	    86	        }
361	    87	        for font in fonts {
