413	   139	    /// G-47 (d) over the store's scan and the disk. Throws, writing nothing, for an asset
414	   140	    /// whose name holds a different picture, or with no store.
415	   141	    static func make(_ contents: GraphicPackageContents, document: ProjectDocument) throws
416	   142	        -> GraphicImportPlan
417	   143	    {
418	   144	        guard let store = document.graphicStore else {
419	   145	            throw ReelCoreError(message: ProjectDocument.noGraphicsFolderSentence)
420	   146	        }
421	   147	        let folder = store.folderURL
422	   148	        let free = { (name: String) in
423	   149	            !store.holdsModule(named: name) && document.graphicClips(named: name).isEmpty
424	   150	        }
425	   151	        let module: GraphicImportPlacement
426	   152	        let held = try? Data(contentsOf: folder.appendingPathComponent(contents.module + ".js"))
427	   153	        if free(contents.module) {
428	   154	            module = .init(name: contents.module, target: contents.module, action: .written)
429	   155	        } else if held == contents.source {
430	   156	            module = .init(name: contents.module, target: contents.module, action: .reused)
431	   157	        } else {
432	   158	            let root = String(String.UnicodeScalarView(contents.module.unicodeScalars.prefix(60)))
433	   159	            var n = 2
434	   160	            while !free("\(root)-\(n)") { n += 1 }
435	   161	            module = .init(name: contents.module, target: "\(root)-\(n)", action: .written)
436	   162	        }
437	   163	        var fonts = Names(folder.appendingPathComponent(GraphicStore.fontsFolderName))
438	   164	        let fontPlaces = contents.fonts.map { font -> GraphicImportPlacement in
439	   165	            var target = font.name
440	   166	            var n = 2
441	   167	            while true {
442	   168	                if let action = fonts.place(target, font.bytes) {
443	   169	                    return .init(name: font.name, target: target, action: action)
444	   170	                }
445	   171	                target = GraphicAssetName.withSuffix(font.name, n)
446	   172	                n += 1
447	   173	            }
448	   174	        }
449	   175	        var assets = Names(folder.appendingPathComponent(GraphicStore.assetsFolderName))
450	   176	        let assetPlaces = try contents.assets.map { asset -> GraphicImportPlacement in
451	   177	            guard let action = assets.place(asset.name, asset.bytes) else {
452	   178	                throw ReelCoreError(
453	   179	                    message: "graphics/assets/\(asset.name) already holds a different picture, "
454	   180	                        + "and this graphic reaches its own by asset(\"\(asset.name)\"), so it "
455	   181	                        + "cannot be renamed; rename or remove the project's file and import "
456	   182	                        + "again")
457	   183	            }
458	   184	            return .init(name: asset.name, target: asset.name, action: action)
459	   185	        }
460	   186	        return GraphicImportPlan(
461	   187	            contents: contents, module: module, fonts: fontPlaces, assets: assetPlaces)
462	   188	    }
