   146	                < ($1.element.t, $1.element.row.order, $1.offset)
   147	        }.map(\.element)
   148	        guard sorted.count > pageSize else { return (sorted, nil) }
   149	        let next = sorted[pageSize].t
   150	        var kept = sorted.prefix { $0.t < next }
   151	        if kept.isEmpty {
   152	            let first = sorted[0].t
   153	            kept = sorted.prefix { $0.t == first }
