352	   148	        settings: ShortcutOverlaySettings, from: Ticks?, to: Ticks?
353	   149	    ) throws -> (plan: ShortcutOverlayPlan, module: String, written: Bool) {
354	   150	        guard let store = document.graphicStore else {
355	   151	            throw AutoZoom.Refusal(message: ProjectDocument.noGraphicsFolderSentence + ".")
356	   152	        }
357	   153	        let template = try template()
358	   154	        let snapshot = document.editedProject.snapshot
359	   155	        let clips = ids.compactMap { snapshot.clip($0) }
360	   156	        func planned(_ module: String) throws -> ShortcutOverlayPlan {
361	   157	            try plan(
362	   158	                clips, tracks: tracks, project: document.editedProject, settings: settings,
363	   159	                module: module, schema: template.schema, from: from, to: to)
364	   160	        }
