97	    97	/// D_min(n) = 10n + 25 frames (CU-80): `keyboard-keys.js` presses its last
98	    98	/// keycap at frame `pressAt + 5(n − 1)` = 10n + 9 (`pressAt` = 5n + 14) and
99	    99	/// exits over the clip's last 15 frames, so the last press needs 16 frames
100	   100	/// before the end.
101	   101	pub(crate) fn min_frames(keycaps: usize) -> i64 {
102	   102	    10 * keycaps as i64 + 25
103	   103	}
104	   104	
105	   105	/// A chord's keycap count: its non-empty trimmed `+` tokens, the template's
106	   106	/// own split.
107	   107	fn keycaps(keys: &str) -> usize {
108	   108	    keys.split('+').filter(|t| !t.trim().is_empty()).count()
109	   109	}
110	   110	
111	   111	/// One press in container frames.
112	   112	struct Press {
113	   113	    frame: i64,
114	   114	    keys: String,
115	   115	}
116	   116	
117	   117	/// One overlay in container frames, `[start, end)`.
118	   118	struct Overlay {
119	   119	    start: i64,
120	   120	    end: i64,
121	   121	    keys: String,
122	   122	    n: usize,
123	   123	    count: u32,
124	   124	}
