126	   126	/// The overlays CU-80 makes of `presses` (in time order): the overlays,
127	   127	/// the presses dropped and the presses merged.
128	   128	fn lay_out(presses: &[Press], duration: i64, most_late: i64) -> (Vec<Overlay>, u32, u32) {
129	   129	    let (mut out, mut dropped, mut merged): (Vec<Overlay>, u32, u32) = (Vec::new(), 0, 0);
130	   130	    for p in presses {
131	   131	        let n = keycaps(&p.keys);
132	   132	        let length = duration.max(min_frames(n));
133	   133	        let mut start = p.frame;
134	   134	        if let Some(cur) = out.last_mut() {
135	   135	            if p.frame < cur.end {
136	   136	                if p.keys == cur.keys {
137	   137	                    cur.end = cur.end.max(p.frame + duration);
138	   138	                    cur.count += 1;
139	   139	                    merged += 1;
140	   140	                    continue;
141	   141	                }
142	   142	                start = p.frame.max(cur.start + min_frames(cur.n));
143	   143	                if start - p.frame > most_late {
144	   144	                    dropped += 1;
145	   145	                    continue;
146	   146	                }
147	   147	                cur.end = start;
148	   148	            }
149	   149	        }
150	   150	        out.push(Overlay {
151	   151	            start,
152	   152	            end: start + length,
153	   153	            keys: p.keys.clone(),
154	   154	            n,
155	   155	            count: 1,
156	   156	        });
157	   157	    }
158	   158	    (out, dropped, merged)
159	   159	}
