163	   163	    for (i, &id) in clips.iter().enumerate() {
164	   164	        if clips[..i].contains(&id) {
165	   165	            return Err(format!("clip {id} is named twice"));
166	   166	        }
167	   167	        let clip = project.require_clip(id)?;
168	   168	        let Source::Media {
169	   169	            media, reversed, ..
170	   170	        } = &clip.source
171	   171	        else {
172	   172	            return Err(format!("clip {id} is not a media clip"));
173	   173	        };
174	   174	        if project
175	   175	            .media(*media)
176	   176	            .and_then(|m| m.cursor.as_ref())
177	   177	            .is_none()
178	   178	        {
179	   179	            return Err(format!("clip {id}'s media {media} has no cursor file"));
180	   180	        }
181	   181	        if *reversed {
182	   182	            return Err(format!(
183	   183	                "clip {id} plays reversed; Add Shortcut Overlays places only clips that play \
184	   184	                 forward"
185	   185	            ));
186	   186	        }
187	   187	    }
