191	   191	/// The track CU-83 picks for the span `[from, to)`: the id and whether it
192	   192	/// is new.
193	   193	fn track_for(project: &Project, clips: &[u32], span: (Ticks, Ticks)) -> (u32, bool) {
194	   194	    let index_of = |track: u32| project.tracks.iter().position(|t| t.id == track);
195	   195	    let front_of_clips = clips
196	   196	        .iter()
197	   197	        .filter_map(|&id| project.clip(id))
198	   198	        .filter_map(|c| index_of(c.track))
199	   199	        .max()
200	   200	        .unwrap_or(0);
201	   201	    let found = project
202	   202	        .tracks
203	   203	        .iter()
204	   204	        .enumerate()
205	   205	        .rev()
206	   206	        .find(|(_, t)| t.name == TRACK_NAME);
207	   207	    if let Some((index, track)) = found {
208	   208	        let free = !project.clips.iter().any(|c| {
209	   209	            c.track == track.id && c.start < span.1 && span.0 < c.start.saturating_add(c.duration)
210	   210	        });
211	   211	        if index > front_of_clips && !track.locked && !track.hidden && track.matte.is_none() && free
212	   212	        {
213	   213	            return (track.id, false);
214	   214	        }
215	   215	    }
216	   216	    (project.next_id, true)
217	   217	}
