219	   219	/// Answers `plan_overlays` (CU-80…CU-84) against `tracks`, one per clip.
220	   220	pub(crate) fn plan_overlays(
221	   221	    tracks: &[&CursorTrack],
222	   222	    project: &Project,
223	   223	    args: PlanOverlaysArgs,
224	   224	) -> Result<Value, String> {
225	   225	    let (lo, hi) = DURATION_RANGE;
226	   226	    if !(args.duration.is_finite() && (lo..=hi).contains(&args.duration)) {
227	   227	        return Err(format!(
228	   228	            "duration is {} s; it runs {lo}–{hi}",
229	   229	            args.duration
230	   230	        ));
231	   231	    }
232	   232	    if let (Some(from), Some(to)) = (args.from, args.to) {
233	   233	        if to <= from {
234	   234	            return Err(format!("to ({to}) must be after from ({from})"));
235	   235	        }
236	   236	    }
237	   237	    if args.clips.is_empty() {
238	   238	        return Err("plan_overlays needs at least one clip".into());
239	   239	    }
240	   240	    if tracks.len() != args.clips.len() {
241	   241	        return Err(format!(
242	   242	            "plan_overlays reads one cursor track per clip; {} clips and {} tracks were given",
243	   243	            args.clips.len(),
244	   244	            tracks.len()
245	   245	        ));
246	   246	    }
247	   247	    check(project, &args.clips)?;
248	   248	    let fps = project.canvas.fps;
249	   249	    let frame = project.frame();
250	   250	    let index = |t: Ticks| time::frame_index(t, fps).unwrap_or(t / frame);
251	   251	    let tick = |i: i64| time::tick_at_frame(i, fps).unwrap_or(i * frame);
252	   252	    let window = (
253	   253	        args.from.unwrap_or(Ticks::MIN),
254	   254	        args.to.unwrap_or(Ticks::MAX),
255	   255	    );
256	   256	    let mut presses: Vec<Press> = Vec::new();
257	   257	    for (i, &id) in args.clips.iter().enumerate() {
258	   258	        let clip = project.require_clip(id)?;
259	   259	        let Some((_, source_in)) = media_in(clip) else {
260	   260	            continue;
261	   261	        };
262	   262	        let length = project.content_length_in_source(clip);
263	   263	        let k = &tracks[i].file().keys.shortcut;
264	   264	        for j in 0..k.t.len() {
265	   265	            let s = us_to_ticks(k.t[j]);
266	   266	            if s < source_in || s >= source_in.saturating_add(length) {
267	   267	                continue;
268	   268	            }
269	   269	            let at = clip.start.saturating_add(clip_time(clip, s - source_in));
270	   270	            if at < window.0 || at >= window.1 {
271	   271	                continue;
272	   272	            }
273	   273	            presses.push(Press {
274	   274	                frame: index(project.snapped(at)),
275	   275	                keys: k.keys[j].clone(),
276	   276	            });
277	   277	        }
278	   278	    }
279	   279	    // Stable: equal frames keep the given clip order.
280	   280	    presses.sort_by_key(|p| p.frame);
281	   281	    let duration = index(seconds_to_ticks(args.duration));
282	   282	    let most_late = index(seconds_to_ticks(MOST_LATE));
283	   283	    let (overlays, dropped, merged) = lay_out(&presses, duration, most_late);
284	   284	    let (Some(first), Some(last)) = (overlays.first(), overlays.last()) else {
285	   285	        return Ok(json!({
286	   286	            "ops": [], "added": 0, "dropped": dropped, "merged": merged,
287	   287	            "track": null, "new_track": false, "overlays": [],
288	   288	        }));
289	   289	    };
290	   290	    let span = (tick(first.start), tick(last.end));
291	   291	    let (track, new_track) = track_for(project, &args.clips, span);
292	   292	    let mut ops: Vec<Value> = Vec::new();
293	   293	    if new_track {
294	   294	        ops.push(json!({"op": "add_track", "index": project.tracks.len(), "name": TRACK_NAME}));
295	   295	    }
296	   296	    let mut answered: Vec<Value> = Vec::new();
297	   297	    for o in &overlays {
298	   298	        let at = tick(o.start);
299	   299	        let length = tick(o.end) - at;
300	   300	        let label = if o.count > 1 {
301	   301	            format!("×{}", o.count)
302	   302	        } else {
303	   303	            String::new()
304	   304	        };
305	   305	        let mut op = json!({
306	   306	            "op": "add_graphic_clip", "track": track, "at": at, "duration": length,
307	   307	            "name": args.module,
308	   308	            "props": {"keys": o.keys, "label": label, "position": args.position.name(),
309	   309	                      "theme": args.theme.name()},
310	   310	        });
311	   311	        if let Some(schema) = &args.schema {
312	   312	            op["schema"] = schema.clone();
313	   313	        }
314	   314	        ops.push(op);
315	   315	        answered.push(json!({"at": at, "duration": length, "keys": o.keys, "label": label}));
316	   316	    }
317	   317	    Ok(json!({
318	   318	        "ops": ops, "added": overlays.len(), "dropped": dropped, "merged": merged,
319	   319	        "track": track, "new_track": new_track, "overlays": answered,
320	   320	    }))
321	   321	}
