421	   100	/// CU-91 (1): `clip`'s typing stretches, clamped to its played window, in
422	   101	/// container time, inside `window`.
423	   102	fn stretches_of(
424	   103	    project: &Project,
425	   104	    clip: &Clip,
426	   105	    track: &CursorTrack,
427	   106	    window: (Ticks, Ticks),
428	   107	) -> Vec<(Ticks, Ticks)> {
429	   108	    let Some((_, source_in)) = media_in(clip) else {
430	   109	        return Vec::new();
431	   110	    };
432	   111	    let source_end = source_in.saturating_add(project.content_length_in_source(clip));
433	   112	    let mut out = Vec::new();
434	   113	    for (first, last, _) in typing_stretches(&track.file().keys.typed.t) {
435	   114	        let (s0, s1) = (us_to_ticks(first).max(source_in), us_to_ticks(last));
436	   115	        let s1 = s1.min(source_end);
437	   116	        if s1 <= s0 {
438	   117	            continue;
439	   118	        }
440	   119	        let at = |s: Ticks| clip.start.saturating_add(clip_time(clip, s - source_in));
441	   120	        let (a, b) = (at(s0).max(window.0), at(s1).min(window.1));
442	   121	        if b > a {
443	   122	            out.push((a, b));
444	   123	        }
445	   124	    }
446	   125	    out
447	   126	}
