449	   128	/// CU-91 (2b): every recorded shortcut's overlay span for `clip`, with no
450	   129	/// `[from, to)` filter on the presses.
451	   130	fn overlay_spans(project: &Project, clip: &Clip, track: &CursorTrack) -> Vec<(Ticks, Ticks)> {
452	   131	    let shortcuts: BTreeSet<u32> = project
453	   132	        .tracks
454	   133	        .iter()
455	   134	        .filter(|t| t.name == TRACK_NAME)
456	   135	        .map(|t| t.id)
457	   136	        .collect();
458	   137	    let late = seconds_to_ticks(MOST_LATE);
459	   138	    let fallback = seconds_to_ticks(DEFAULT_DURATION);
460	   139	    let mut out = Vec::new();
461	   140	    for &t in &track.file().keys.shortcut.t {
462	   141	        let Some(p) = played_at(project, clip, us_to_ticks(t)) else {
463	   142	            continue;
464	   143	        };
465	   144	        let before = out.len();
466	   145	        for c in project
467	   146	            .clips
468	   147	            .iter()
469	   148	            .filter(|c| shortcuts.contains(&c.track))
470	   149	        {
471	   150	            let holds = c.start <= p && p < end(c);
472	   151	            let soon = p < c.start && c.start <= p.saturating_add(late);
473	   152	            if holds || soon {
474	   153	                out.push((p.min(c.start), end(c)));
475	   154	            }
476	   155	        }
477	   156	        if out.len() == before {
478	   157	            out.push((p, p.saturating_add(fallback)));
479	   158	        }
480	   159	    }
481	   160	    out
482	   161	}
