484	   163	/// `piece` less every span of `cuts`.
485	   164	fn subtract(piece: (Ticks, Ticks), cuts: &[(Ticks, Ticks)]) -> Vec<(Ticks, Ticks)> {
486	   165	    let mut left = vec![piece];
487	   166	    for &(c0, c1) in cuts {
488	   167	        left = left
489	   168	            .into_iter()
490	   169	            .flat_map(|(a, b)| {
491	   170	                if c1 <= a || b <= c0 {
492	   171	                    return vec![(a, b)];
493	   172	                }
494	   173	                [(a, c0.min(b)), (c1.max(a), b)]
495	   174	                    .into_iter()
496	   175	                    .filter(|(x, y)| y > x)
497	   176	                    .collect()
498	   177	            })
499	   178	            .collect();
500	   179	    }
501	   180	    left
502	   181	}
