504	   183	/// Pieces sorted and merged where they overlap or touch (CU-91 (3)).
505	   184	fn united(mut pieces: Vec<(Ticks, Ticks)>) -> Vec<(Ticks, Ticks)> {
506	   185	    pieces.sort_unstable();
507	   186	    let mut out: Vec<(Ticks, Ticks)> = Vec::with_capacity(pieces.len());
508	   187	    for (a, b) in pieces {
509	   188	        match out.last_mut() {
510	   189	            Some(last) if a <= last.1 => last.1 = last.1.max(b),
511	   190	            _ => out.push((a, b)),
512	   191	        }
513	   192	    }
514	   193	    out
515	   194	}
