728	    92	/// Checks every clip in CU-75's order; answers each clip's run.
729	    93	fn check<'p>(project: &'p Project, clips: &[u32]) -> Result<Vec<Vec<&'p Clip>>, String> {
730	    94	    let mut runs = Vec::new();
731	    95	    for (i, &id) in clips.iter().enumerate() {
732	    96	        if clips[..i].contains(&id) {
733	    97	            return Err(format!("clip {id} is named twice"));
734	    98	        }
735	    99	        let clip = project.require_clip(id)?;
736	   100	        let Source::Media {
737	   101	            media, reversed, ..
738	   102	        } = &clip.source
739	   103	        else {
740	   104	            return Err(format!("clip {id} is not a media clip"));
741	   105	        };
742	   106	        let found = project.media(*media);
743	   107	        if found.and_then(|m| m.cursor.as_ref()).is_none() {
744	   108	            return Err(format!("clip {id}'s media {media} has no cursor file"));
745	   109	        }
746	   110	        if *reversed {
747	   111	            return Err(format!(
748	   112	                "clip {id} plays reversed; Auto Zoom plans only clips that play forward"
749	   113	            ));
750	   114	        }
751	   115	        let picture = clip.video.is_some() && found.is_some_and(|m| m.has_video);
752	   116	        let Some((sw, sh)) = project.source_size(clip).filter(|_| picture) else {
753	   117	            return Err(format!("clip {id} has no picture"));
754	   118	        };
755	   119	        let run = run_of(project, clip);
756	   120	        let rest = run.first().map_or(1.0, |c| base(c).scale);
757	   121	        if rest < project.fit_scale(sw, sh) * (1.0 - PLACED_TOLERANCE) {
758	   122	            return Err(format!(
759	   123	                "clip {id} is placed smaller than the canvas; a zoom would fill the canvas. \
760	   124	                 Nest it (Clip ▸ Nest) and run Auto Zoom inside the nest."
761	   125	            ));
762	   126	        }
763	   127	        runs.push(run);
764	   128	    }
765	   129	    Ok(runs)
766	   130	}
